# ============================================================================
# Combine all courses
# ============================================================================
ALL_COURSES = (
    COURSE_ALLOCATIONS +
    JOURNALISM_COURSES +
    LINGUISTICS_LIT_COURSES +
    COMMUNICATION_STUDIES_COURSES +
    PHILOSOPHY_COURSES +
    RELIGIOUS_STUDIES_COURSES +
    HISTORY_ECON_COURSES +
    KISWAHILI_GEOGRAPHY_COURSES
)


def get_lecturer(lecturer_name):
    """
    Find a Lecturer by name or payroll number using the LECTURER_MAP.
    """
    if not lecturer_name:
        return None
    
    # First try exact match
    for key, value in LECTURER_MAP.items():
        if key.lower() == lecturer_name.lower():
            if value["payroll"]:
                try:
                    return Lecturer.objects.get(payroll_number=value["payroll"])
                except Lecturer.DoesNotExist:
                    # Try by email or name
                    try:
                        return Lecturer.objects.get(email__icontains=value["name"].split()[0])
                    except Lecturer.DoesNotExist:
                        try:
                            return Lecturer.objects.get(name__icontains=value["name"])
                        except Lecturer.DoesNotExist:
                            logger.warning(f"Lecturer not found: {value['name']} (payroll: {value['payroll']})")
                            return None
            else:
                # Try by name
                try:
                    return Lecturer.objects.get(name__icontains=value["name"])
                except Lecturer.DoesNotExist:
                    # Try by email
                    email_part = value["name"].lower().replace(" ", ".")
                    try:
                        return Lecturer.objects.get(email__icontains=email_part)
                    except Lecturer.DoesNotExist:
                        logger.warning(f"Lecturer not found: {value['name']}")
                        return None
    # If no match, try direct search
    try:
        return Lecturer.objects.get(name__icontains=lecturer_name)
    except Lecturer.DoesNotExist:
        # Try by email
        email_part = lecturer_name.lower().replace(" ", ".")
        try:
            return Lecturer.objects.get(email__icontains=email_part)
        except Lecturer.DoesNotExist:
            logger.warning(f"Lecturer not found: {lecturer_name}")
            return None


def get_program(program_name):
    """Find a Program by name."""
    if not program_name:
        return None
    try:
        return Program.objects.get(name__iexact=program_name)
    except Program.DoesNotExist:
        # Try partial match
        matches = Program.objects.filter(name__icontains=program_name)
        if matches.exists():
            return matches.first()
        logger.warning(f"Program not found: {program_name}")
        return None


def get_program_course(program, course_code):
    """Find a ProgramCourse by program and course code."""
    if not program or not course_code:
        return None
    matches = ProgramCourse.objects.filter(program=program, course_code__iexact=course_code)
    count = matches.count()
    if count == 0:
        logger.warning(f"ProgramCourse not found: {course_code} for {program.name if program else 'None'}")
        return None
    if count > 1:
        logger.warning(
            f"Multiple ProgramCourse rows ({count}) found for {course_code} in "
            f"{program.name} — using the lowest id. These duplicates should be "
            f"reviewed/cleaned up in the curriculum data."
        )
    return matches.order_by("id").first()


def get_student_group(program, year, semester, letter, intake="normal"):
    """Find an existing StudentGroup by program, year, semester, letter, and intake."""
    if not program or not letter:
        return None
    try:
        return StudentGroup.objects.get(
            program=program,
            year=year,
            semester=semester,
            letter=letter,
            intake=intake,
        )
    except StudentGroup.DoesNotExist:
        logger.warning(
            f"StudentGroup not found: {program.name} Y{year}S{semester} "
            f"Group {letter} ({intake} intake)"
        )
        return None
    except StudentGroup.MultipleObjectsReturned:
        logger.warning(
            f"Multiple StudentGroup rows found for {program.name} Y{year}S{semester} "
            f"Group {letter} ({intake} intake) — using the lowest id."
        )
        return StudentGroup.objects.filter(
            program=program, year=year, semester=semester, letter=letter, intake=intake
        ).order_by("id").first()


def parse_group_letters(note):
    """
    Extract student-group letters (A, B, C, ...) from a free-text _group_note
    like 'GRP A&B - 300 students', 'GRPC-CB1-Alex Kinyua', 'Group A', or
    'All groups A-D'.

    Returns:
        - a sorted list of letters, e.g. ['A', 'B'], if specific groups were found
        - None if the note implies the course is shared across all groups
          (no note, or an "All groups ..." note), or if nothing could be parsed
    """
    if not note:
        return None
    if "all group" in note.lower():
        return None

    letters = set()
    # "GRP A", "GRPA", "GRP A&B", "GRPC-CB1-...", "GRPE=CB8-..." — the literal
    # "GRP" prefix anchors the match so room codes like "AB1"/"CB1"/"CB8"
    # (which never follow "GRP") are never mistaken for group letters.
    for m in re.finditer(r"GRP\s*([A-Z])(?:\s*[&,]\s*([A-Z]))?", note):
        letters.add(m.group(1))
        if m.group(2):
            letters.add(m.group(2))
    # "Group A", "Group B", ...
    for m in re.finditer(r"\bGroup\s+([A-Z])\b", note):
        letters.add(m.group(1))

    if not letters:
        logger.warning(f"Could not parse group letters from note: {note!r}")
        return None
    return sorted(letters)


def run():
    """Main entry point for the seed script."""
    print("=" * 80)
    print("SEEDING HUMANITIES COURSE ALLOCATIONS")
    print("=" * 80)
    
    # Get the Humanities department
    try:
        humanities_dept = Department.objects.get(name="Humanities")
        print(f"Found department: {humanities_dept.name}")
    except Department.DoesNotExist:
        print("ERROR: Humanities department not found!")
        return
    
    # Count existing allocations
    existing_count = CourseAllocation.objects.filter(department=humanities_dept).count()
    print(f"Existing CourseAllocations for Humanities: {existing_count}")
    
    if existing_count > 0:
        print("Deleting existing allocations...")
        deleted_count, _ = CourseAllocation.objects.filter(department=humanities_dept).delete()
        print(f"Deleted {deleted_count} allocations.")
    
    created_count = 0
    error_count = 0
    skipped_count = 0
    
    print("\nProcessing allocations...")
    
    for idx, course_data in enumerate(ALL_COURSES):
        program = get_program(course_data.get("program"))
        if not program:
            print(f"  [{idx}] SKIP: Program not found - {course_data.get('program')}")
            skipped_count += 1
            continue
        
        program_course = get_program_course(program, course_data["unit_code"])
        if not program_course:
            print(f"  [{idx}] SKIP: ProgramCourse not found - {course_data['unit_code']} for {program.name}")
            skipped_count += 1
            continue
        
        lecturer = get_lecturer(course_data.get("lecturer"))
        if not lecturer and course_data.get("lecturer"):
            print(f"  [{idx}] WARNING: Lecturer not found - {course_data.get('lecturer')}")

        intake = course_data.get("intake", "normal")

        # Resolve which student group(s), if any, this entry applies to.
        # Explicit student_group_letter wins if set; otherwise fall back to
        # parsing the free-text _group_note (see parse_group_letters()).
        explicit_letter = course_data.get("student_group_letter")
        if explicit_letter:
            group_letters = [explicit_letter]
        else:
            group_letters = parse_group_letters(course_data.get("_group_note"))

        # group_letters is None => single shared row (student_group=None).
        # group_letters is a list => one row per letter, each linked to its
        # StudentGroup (looked up, never created — they're expected to
        # already exist).
        if group_letters is None:
            targets = [(None, "")]
        else:
            targets = []
            for letter in group_letters:
                sg = get_student_group(program, course_data["year"], course_data["semester"], letter, intake)
                if sg is None:
                    print(f"  [{idx}] SKIP group {letter}: StudentGroup not found - "
                          f"{program.name} Y{course_data['year']}S{course_data['semester']} Group {letter} ({intake})")
                    skipped_count += 1
                    continue
                targets.append((sg, f" [Group {letter}]"))

        for student_group, label in targets:
            try:
                allocation = CourseAllocation(
                    department=humanities_dept,
                    program=program,
                    program_course=program_course,
                    course_code=course_data["unit_code"],
                    course_name=course_data["course_name"],
                    lecturer=lecturer,
                    number_of_students=course_data.get("students") or 0,
                    intake=intake,
                    is_elective=course_data.get("is_elective", False),
                    is_evening_weekend=False,
                    approved_by_dvc=False,
                    rejected_by_dvc=False,
                    submitted_to_tt=False,
                    student_group=student_group,
                )
                allocation.full_clean()
                allocation.save()
                created_count += 1

                if created_count % 20 == 0:
                    print(f"  [{idx}] Created: {course_data['unit_code']}{label} - {course_data['course_name'][:30]}...")

            except Exception as e:
                print(f"  [{idx}] ERROR creating {course_data['unit_code']}{label}: {str(e)}")
                error_count += 1
    
    print("\n" + "=" * 80)
    print("SUMMARY")
    print("=" * 80)
    print(f"Total processed: {len(ALL_COURSES)}")
    print(f"Created: {created_count}")
    print(f"Skipped: {skipped_count}")
    print(f"Errors: {error_count}")
    print("=" * 80)

# scripts/seed_humanities_allocations.py
